function M.warn(_msg) end
function M.warn_once(key, message)
    local k = "warn:" .. tostring(key)
    if seen_errors[k] then return end
    seen_errors[k] = 1
    print("[JMTECH] Warning (" .. tostring(key) .. "): " .. tostring(message))
end
function M.error_once(key, err)
    local k = "error:" .. tostring(key)
    local count = seen_errors[k] or 0
    seen_errors[k] = count + 1
    if count == 0 then
        print("[JMTECH] Error (" .. tostring(key) .. "): " .. tostring(err))
    end
end
function M.guard(key, fn, ...)
    return M.guard_fast(key, fn, ...)
end
function M.guard_fast(key, fn, ...)
    if type(fn) ~= "function" then return nil end
    local ok, a, b, c = pcall(fn, ...)
    if not ok then
        M.error_once(key, a)
        return nil
    end
    return a, b, c
end
function M.guard_bool(key, fn, ...)
    if type(fn) ~= "function" then return false end
    local ok, result = pcall(fn, ...)
    if not ok then
        M.error_once(key, result)
        return false
    end
    return true, result
end
function M.register_frame_hook(fn)
    if type(fn) ~= "function" then
        return false
    end
    _G.OnFrame = fn
    _G.onFrame = fn
    _G.on_frame = fn
    if callbacks and callbacks.add then
        pcall(callbacks.add, "on_frame", fn)
        pcall(callbacks.add, "OnFrame", fn)
    end
    if draw then
        draw.callback = fn
    end
    return true
end
function M.tick_frame()
    frame_count = frame_count + 1
end
function M.frame_count()
    return frame_count
end
function M.reset_errors()
    seen_errors = {}
end
function M.stats()
    return { frames = frame_count, errors = seen_errors }
end
return M
end)()

