function M.short_label(role)
    if not role then return "STAFF" end
    if role == "Game Moderator" then return "MOD" end
    if role == "Game Tester" then return "TESTER" end
    if role == "Lead Developer" or role == "Developers" then return "DEV" end
    if role == "Co-Founder" then return "CO-FOUNDER" end
    if role == "Founder" then return "FOUNDER" end
    if role == "OG" then return "OG" end
    if role == "Contribution" then return "CONTRIB" end
    return role:upper()
end
function M.glyph_kind(role)
    if not role then return "staff" end
    local r = role:lower()
    if r:find("moderator", 1, true) then return "mod" end
    if r:find("tester", 1, true) then return "tester" end
    if r:find("developer", 1, true) or r:find("founder", 1, true) then return "dev" end
    if r == "og" then return "og" end
    if r:find("contribution", 1, true) then return "contrib" end
    return "staff"
end
local function normalize_uid(user_id)
    local uid = tonumber(user_id)
    if not uid or uid == 0 then return nil end
    return uid
end
M._player_roles = {}
local function mod_group()
    return JMTECH.require("game.mod_group")
end
local function player_state()
    return JMTECH.require("game.player_state")
end
function M.reset_session()
    M._player_roles = {}
    local group = mod_group()
    if group.reset_session then
        group.reset_session()
    end
end
function M.clear_role_cache()
    M._player_roles = {}
end
function M.invalidate_uid(user_id)
    local uid = normalize_uid(user_id)
    if uid then
        M._player_roles[uid] = nil
    end
end
local function player_uid(player)
    local ep = JMTECH.require("core.entity_props")
    return normalize_uid(ep.user_id(player))
end
local function cache_key(player)
    local uid = player_uid(player)
    if uid then return uid end
    return player.name or player.display_name
end
local function read_cached_role(key)
    if key == nil then return nil, false end
    if M._player_roles[key] == nil then
        return nil, false
    end
    local cached = M._player_roles[key]
    if cached == false then return nil, true end
    return cached, true
end
local function write_cached_role(key, role)
    if key == nil then return end
    M._player_roles[key] = role or false
end
local function role_from_game_tag(player)
    local tag = player_state().staff_tag(player)
    if tag == "OWNER" then return "Founder" end
    if tag == "ADMIN" then return "Developers" end
    if tag == "MOD" then return "Game Moderator" end
    return nil
end
function M.role_for(user_id)
    local uid = normalize_uid(user_id)
    if not uid then return nil end
    local group = mod_group()
    if group.available() then
        local live = group.role_for(uid)
        if live then return live end
    end
    return M.ROLES[uid]
end
function M.role_for_player(player, opts)
    if not player or player.is_local then return nil end
    opts = opts or {}
    local key = cache_key(player)
    local cached, hit = read_cached_role(key)
    if hit then
        return cached
    end
    local tag_role = role_from_game_tag(player)
    if tag_role then
        local uid = player_uid(player)
        if uid then
            local precise = opts.live_lookup == false and M.ROLES[uid] or M.role_for(uid)
            if precise then
                write_cached_role(key, precise)
                return precise
            end
        end
        write_cached_role(key, tag_role)
        return tag_role
    end
    local uid = player_uid(player)
    if not uid then
        return nil
    end
    local group = mod_group()
    if opts.live_lookup ~= false and group.available() then
        local live = group.role_for(uid)
        if live then
            write_cached_role(key, live)
            return live
        end
        if opts.queue_lookup and group.is_started and group.is_started() then
            group.queue_lookup(uid)
        end
    end
    local static_role = M.ROLES[uid]
    if static_role then
        write_cached_role(key, static_role)
        return static_role
    end
    if opts.mark_unknown then
        write_cached_role(key, false)
    end
    return nil
end
function M.is_mod(user_id)
    return M.role_for(user_id) ~= nil
end
function M.is_staff_player(player)
    return M.role_for_player(player) ~= nil
end
function M.ensure_started()
    local group = mod_group()
    if group.available() then
        return group.ensure_started()
    end
    return false
end
function M.stop(reason)
    local group = mod_group()
    if group.stop then group.stop(reason) end
end
function M.tick()
    M.ensure_started()
end
function M.invalidate_player(player)
    if not player then return end
    local key = cache_key(player)
    if key ~= nil then
        M._player_roles[key] = nil
    end
end
return M
end)()

JMTECH._mods["game.mod_group"] = (function()
local debug = JMTECH.require("core.debug")
local M = {}
M.GROUP_ID = 1154360
M.MIN_STAFF_RANK = 6
M._cache = {}
M._cache_ready = false
M._cache_at = 0
M._refresh_ms = 30 * 60 * 1000
M._started = false
M._thread_id = nil
local TICK_MS = 3500
local RATE_LIMIT_MS = 15 * 60 * 1000
local RETRY_BASE_MS = 30 * 1000
local RETRY_MAX_MS = 10 * 60 * 1000
local MAX_QUEUE = 64
local MAX_PAGES = 80
local MAX_ROLES = 32
local MAX_TOTAL_PAGES = 256
local MAX_STAFF_ENTRIES = 10000
local MAX_BODY_BYTES = 2 * 1024 * 1024
local lookup_queue = {}
local lookup_pending = {}
local lookup_seen = {}
local lookup_attempts = {}
local crawl = nil
local next_attempt_at = 0
local crawl_failure_count = 0
local lookup_failure_count = 0
local loaded_notified = false
local tick_busy = false
local function tick_ms()
    local fn = utility and (utility.get_tick_count or utility.GetTickCount)
    if type(fn) ~= "function" then return 0 end
    local ok, value = pcall(fn)
    return ok and (tonumber(value) or 0) or 0
end
local function log(message)
    debug.file("STAFF_CRAWLER " .. tostring(message))
end
local function normalize_uid(value)
    local uid = tonumber(value)
    return uid and uid ~= 0 and uid or nil
end
local function http_fn()
    return utility and (utility.http_get or utility.HttpGet) or nil
end
local function status_code(status)
    local code = tonumber(status)
    if code then return code end
    if type(status) == "string" then return tonumber(status:match("(%d%d%d)")) end
    return nil
end
local function request(url)
    local fn = http_fn()
    if type(fn) ~= "function" then return nil, "no HttpGet", nil end
    local ok, body, status = pcall(fn, url)
    if not ok then return nil, tostring(body), nil end
    local code = status_code(status)
    if type(body) == "string" and #body > MAX_BODY_BYTES then
        return nil, "response too large", code
    end
    if type(body) ~= "string" or body == "" then
        return nil, tostring(status or "empty response"), code
    end
    if code and (code < 200 or code >= 300) then
        return nil, "HTTP " .. tostring(code), code
    end
    return body, nil, code or 200
end
local function cache_count(tbl)
    local count = 0
    for _ in pairs(tbl or {}) do count = count + 1 end
    return count
end
local function url_encode(value)
    return (tostring(value or ""):gsub("([^%w%-_%.%~])", function(ch)
        return string.format("%%%02X", string.byte(ch))
    end))
end
local function parse_cursor(body)
    if not body or body:find('"nextPageCursor"%s*:%s*null') then return nil end
    local cursor = body:match('"nextPageCursor"%s*:%s*"([^"]+)"')
    return cursor ~= "" and cursor ~= "null" and cursor or nil
end
local function parse_roles(body)
    local roles = {}
    local overflow = false
    local payload = body and (body:match('"roles"%s*:%s*(%b[])') or body) or ""
    for block in payload:gmatch("%b{}") do
        local id = tonumber(block:match('"id"%s*:%s*(%d+)'))
        local name = block:match('"name"%s*:%s*"([^"]+)"')
        local rank = tonumber(block:match('"rank"%s*:%s*(%d+)'))
        local members = tonumber(block:match('"memberCount"%s*:%s*(%d+)')) or 0
        if id and name and rank and rank >= M.MIN_STAFF_RANK then
            if #roles >= MAX_ROLES then
                overflow = true
            else
                roles[#roles + 1] = {
                    id = id,
                    name = name,
                    rank = rank,
                    members = members,
                    loaded = 0,
                    pages = 0,
                }
            end
        end
    end
    table.sort(roles, function(a, b) return a.rank > b.rank end)
    return roles, overflow
end
local function parse_role_users(body, role_name, out, max_new)
    local added = 0
    for uid_text in tostring(body or ""):gmatch('"userId"%s*:%s*(%d+)') do
        local uid = tonumber(uid_text)
        if uid then
            if out[uid] == nil then
                if added >= max_new then return added, true end
                added = added + 1
            end
            out[uid] = role_name
        end
    end
    return added, false
end
local function parse_user_role(body)
    local gid = tostring(M.GROUP_ID)
    local pos = 1
    while true do
        local start_at = body:find('"group"', pos, true)
        if not start_at then return nil end
        local chunk = body:sub(start_at, math.min(#body, start_at + 500))
        if chunk:match('"id"%s*:%s*(%d+)') == gid then
            local role = chunk:match('"role"%s*:%s*{(.-)}')
            local rank = role and tonumber(role:match('"rank"%s*:%s*(%d+)'))
            local name = role and role:match('"name"%s*:%s*"([^"]+)"')
            if rank and name then return rank >= M.MIN_STAFF_RANK and name or false end
            return nil
        end
        pos = start_at + 7
    end
end
local function invalidate_role_cache(uid)
    pcall(function()
        local ids = JMTECH.require("game.mod_ids")
        if uid and ids.invalidate_uid then
            ids.invalidate_uid(uid)
        elseif ids.clear_role_cache then
            ids.clear_role_cache()
        end
    end)
end
local function notify_loaded(count, roles)
    if loaded_notified then return end
    loaded_notified = true
    pcall(function()
        JMTECH.require("core.notify").success(string.format(
            "Live staff crawler ready (%d people, %d roles)", count, roles
        ), 5500)
    end)
end
local function abort_crawl()
    crawl = nil
end
local function backoff(reason, code, uid)
    if uid then
        lookup_failure_count = lookup_failure_count + 1
    else
        crawl_failure_count = crawl_failure_count + 1
    end
    local failures = uid and lookup_failure_count or crawl_failure_count
    local now = tick_ms()
    local delay
    if code == 429 then
        delay = RATE_LIMIT_MS
    else
        delay = math.min(RETRY_BASE_MS * (2 ^ math.min(failures - 1, 5)), RETRY_MAX_MS)
    end
    next_attempt_at = now + delay
    abort_crawl()
    if uid and (lookup_attempts[uid] or 0) < 3 and not lookup_pending[uid] then
        lookup_pending[uid] = true
        lookup_queue[#lookup_queue + 1] = uid
    end
    log(string.format(
        "backoff reason=%s status=%s delay_ms=%d",
        tostring(reason), tostring(code or "none"), delay
    ))
end
local function begin_crawl()
    crawl = {
        phase = "roles",
        roles = nil,
        role_index = 1,
        cursor = nil,
        staging = {},
        entry_count = 0,
        total_pages = 0,
    }
    log("state=roles")
end
local function commit_crawl()
    local count = cache_count(crawl.staging)
    if count < 1 then
        backoff("empty roster", nil)
        return
    end
    M._cache = crawl.staging
    M._cache_ready = true
    M._cache_at = tick_ms()
    local role_count = #crawl.roles
    crawl = nil
    crawl_failure_count = 0
    next_attempt_at = 0
    invalidate_role_cache()
    log(string.format("commit people=%d roles=%d", count, role_count))
    notify_loaded(count, role_count)
end
local function step_lookup()
    local uid = table.remove(lookup_queue, 1)
    if not uid then return false end
    lookup_pending[uid] = nil
    lookup_attempts[uid] = (lookup_attempts[uid] or 0) + 1
    local body, err, code = request(string.format(
        "https://groups.roblox.com/v2/users/%d/groups/roles", uid
    ))
    if not body then
        backoff("user " .. tostring(uid) .. ": " .. tostring(err), code, uid)
        return true
    end
    local role = parse_user_role(body)
    lookup_seen[uid] = true
    lookup_attempts[uid] = nil
    lookup_failure_count = 0
    if role then
        M._cache[uid] = role
        invalidate_role_cache(uid)
        log("user_match uid=" .. tostring(uid) .. " role=" .. tostring(role))
    end
    return true
end
local function step_roles()
    local body, err, code = request(string.format(
        "https://groups.roblox.com/v1/groups/%d/roles", M.GROUP_ID
    ))
    if not body then
        backoff("roles: " .. tostring(err), code)
        return
    end
    local roles, overflow = parse_roles(body)
    if overflow then
        backoff("role limit", code)
        return
    end
    if #roles < 1 then
        backoff("roles: empty response", code)
        return
    end
    crawl.roles = roles
    crawl.role_index = 1
    crawl.cursor = nil
    crawl.phase = "pages"
    log("state=pages roles=" .. tostring(#roles))
end
local function advance_role()
    crawl.role_index = crawl.role_index + 1
    crawl.cursor = nil
    if crawl.role_index > #crawl.roles then commit_crawl() end
end
local function step_page()
    local role = crawl.roles[crawl.role_index]
    if not role then
        commit_crawl()
        return
    end
    role.pages = role.pages + 1
    crawl.total_pages = crawl.total_pages + 1
    if role.pages > MAX_PAGES or crawl.total_pages > MAX_TOTAL_PAGES then
        backoff("page limit for " .. tostring(role.name), nil)
        return
    end
    local url = string.format(
        "https://groups.roblox.com/v1/groups/%d/roles/%d/users?limit=100&sortOrder=Asc",
        M.GROUP_ID, role.id
    )
    if crawl.cursor then url = url .. "&cursor=" .. url_encode(crawl.cursor) end
    local body, err, code = request(url)
    if not body then
        backoff("role " .. tostring(role.name) .. ": " .. tostring(err), code)
        return
    end
    local added, overflow = parse_role_users(
        body, role.name, crawl.staging, MAX_STAFF_ENTRIES - crawl.entry_count
    )
    role.loaded = role.loaded + added
    crawl.entry_count = crawl.entry_count + added
    if overflow then
        backoff("staff entry limit", nil)
        return
    end
    crawl.cursor = parse_cursor(body)
    if not crawl.cursor then
        if role.members > 0 and role.loaded < role.members then
            backoff(string.format(
                "incomplete %s %d/%d", role.name, role.loaded, role.members
            ), nil)
            return
        end
        log(string.format(
            "role_complete name=%s members=%d pages=%d",
            role.name, role.loaded, role.pages
        ))
        advance_role()
    end
end
local function scheduler_tick()
    if not M._started then return end
    local now = tick_ms()
    if now < next_attempt_at then return end
    if step_lookup() then return end
    if not crawl then
        if M._cache_ready and now - M._cache_at < M._refresh_ms then return end
        begin_crawl()
    end
    if crawl.phase == "roles" then
        step_roles()
    elseif crawl.phase == "pages" then
        step_page()
    end
end
local function guarded_tick()
    if tick_busy then return end
    tick_busy = true
    local ok, err = pcall(scheduler_tick)
    tick_busy = false
    if not ok then backoff("scheduler error: " .. tostring(err), nil) end
end
function M.available()
    return type(http_fn()) == "function"
end
function M.is_started()
    return M._started == true
end
function M.role_for(user_id)
    local uid = normalize_uid(user_id)
    return uid and M._cache[uid] or nil
end
function M.is_ready()
    return M._cache_ready == true
end
function M.queue_lookup(user_id)
    local uid = normalize_uid(user_id)
    if not uid or M._cache[uid] or lookup_seen[uid] or lookup_pending[uid] then return end
    if #lookup_queue >= MAX_QUEUE or (lookup_attempts[uid] or 0) >= 3 then return end
    lookup_pending[uid] = true
    lookup_queue[#lookup_queue + 1] = uid
end
function M.lookup_user(user_id)
    M.queue_lookup(user_id)
    return M.role_for(user_id)
end
function M.refresh_all()
    if tick_ms() < next_attempt_at then return false end
    M._cache_at = 0
    abort_crawl()
    return M._started
end
function M.force_refresh()
    loaded_notified = false
    return M.refresh_all()
end
function M.ensure_started()
    if M._started or not M.available() then return M._started end
    local create = thread and (thread.create or thread.Create)
    if type(create) ~= "function" then
        debug.warn_once("mod_group:nothread", "Live staff crawler unavailable: no thread API")
        return false
    end
    M._started = true
    local ok, id = pcall(create, guarded_tick, TICK_MS)
    if not ok or not id then
        M._started = false
        M._thread_id = nil
        debug.error_once("mod_group:start", id or "thread.Create failed")
        return false
    end
    M._thread_id = id
    local first_tick = tick_ms() + TICK_MS
    if next_attempt_at < first_tick then next_attempt_at = first_tick end
    log("started interval_ms=" .. tostring(TICK_MS))
    return true
end
function M.stop(reason)
    if M._thread_id then
        local stop = thread and (thread.stop or thread.Stop)
        if type(stop) == "function" then pcall(stop, M._thread_id) end
    end
    M._thread_id = nil
    M._started = false
    tick_busy = false
    abort_crawl()
    lookup_queue = {}
    lookup_pending = {}
    log("stopped reason=" .. tostring(reason or "disabled"))
end
function M.reset_session()
    M.stop("session_changed")
    lookup_seen = {}
    lookup_attempts = {}
    M._cache_at = 0
end
function M.tick()
    return M.ensure_started()
end
return M
end)()

JMTECH._mods["game.cheater_detect"] = (function()
local ep = JMTECH.require("core.entity_props")
local env = JMTECH.require("core.env")
local M = {}
local AGE_THRESHOLD_DAYS = 60
local VERT_SPEED_ABS = 1000
local RESCAN_MS = 3000
local cache = {}
local last_scan_ms = 0
local function tick_ms()
    return utility and utility.get_tick_count and utility.get_tick_count() or 0
end
local function cache_key(player)
    local uid = ep.user_id(player)
    if uid and uid ~= 0 then
        return "u:" .. tostring(uid)
    end
    local name = ep.name(player)
    if name and name ~= "" then
        return "n:" .. name
    end
    return nil
end
local function read_account_age(player)
    local age = tonumber(ep.get(player, "AccountAge", "account_age"))
    if age then return age end
    local pl = ep.player_inst(player)
    if not pl then return nil end
    local ok, v = pcall(function()
        return pl.AccountAge or pl.account_age
    end)
    if ok then
        return tonumber(v)
    end
    return nil
end
local function vertical_speed(player)
    local vel = ep.velocity(player)
    if vel then
        local y = tonumber(vel.Y or vel.y)
        if y then return y end
    end
    local char = ep.character(player)
    if not char or not env.is_valid(char) then return nil end
    local root = env.safe_call(function()
        return char:FindFirstChild("HumanoidRootPart")
            or char:find_first_child("HumanoidRootPart")
    end)
    if not root or not env.is_valid(root) then return nil end
    local v = root.AssemblyLinearVelocity or root.Velocity or root.velocity
    if not v then return nil end
    return tonumber(v.Y or v.y)
end
local function evaluate(player)
    local age = read_account_age(player)
    if age ~= nil and age <= AGE_THRESHOLD_DAYS then
        return true
    end
    local vy = vertical_speed(player)
    if vy ~= nil and (vy <= -VERT_SPEED_ABS or vy >= VERT_SPEED_ABS) then
        return true
    end
    return false
end
function M.is_cheater(player)
    if not player or ep.is_local(player) then return false end
    local key = cache_key(player)
    if not key then return false end
    local now = tick_ms()
    local entry = cache[key]
    if entry and entry.flagged then
        return true
    end
    if entry and now - (entry.at or 0) < RESCAN_MS then
        return entry.flagged == true
    end
    local flagged = evaluate(player)
    cache[key] = { flagged = flagged, at = now }
    return flagged
end
function M.tick()
    local now = tick_ms()
    if now - last_scan_ms < RESCAN_MS then return end
    last_scan_ms = now
    local players = entity and (entity.get_players or entity.GetPlayers)
    if not players then return end
    local ok, list = pcall(players)
    if not ok or type(list) ~= "table" then return end
    local live = {}
    for i = 1, #list do
        local p = list[i]
        if p and not ep.is_local(p) then
            local key = cache_key(p)
            if key then live[key] = true end
            M.is_cheater(p)
        end
    end
    for key in pairs(cache) do
        if not live[key] then cache[key] = nil end
    end
end
function M.clear()
    cache = {}
    last_scan_ms = 0
end
return M
end)()

JMTECH._mods["core.settings"] = (function()
local M = {}
local _callbacks = {}
local feature_bind = nil
local _frame = 0
local _value_cache = {}
local _color_cache = {}
local NIL = {}
local function clear_table(t)
    for key in pairs(t) do t[key] = nil end
end
function M.begin_frame(frame)
    frame = tonumber(frame) or (_frame + 1)
    if frame == _frame then return end
    _frame = frame
    clear_table(_value_cache)
    clear_table(_color_cache)
end
function M.frame()
    return _frame
end
function M.invalidate(id)
    if id ~= nil then
        _value_cache[id] = nil
        _color_cache[id] = nil
        return
    end
    clear_table(_value_cache)
    clear_table(_color_cache)
end
function M.get(id, default)
    local cached = _value_cache[id]
    if cached ~= nil then
        if cached == NIL then return default end
        return cached
    end
    if menu and menu.get then
        local v = menu.get(id)
        _value_cache[id] = v == nil and NIL or v
        if v ~= nil then return v end
    end
    _value_cache[id] = NIL
    return default
end
function M.bool(id, default)
    local v = M.get(id, default)
    if v == false or v == 0 or v == "false" then return false end
    return v == true or v == 1
end
function M.enabled(id)
    if not feature_bind then
        local ok, fb = pcall(JMTECH.require, "core.feature_bind")
        if ok then feature_bind = fb end
    end
    if feature_bind and feature_bind.is_registered(id) then
        return feature_bind.active(id)
    end
    return M.bool(id, false)
end
function M.num(id, default)
    return tonumber(M.get(id, default)) or default or 0
end
local function as_bool(v, default)
    if v == nil then
        return default == true
    end
    if v == true or v == 1 or v == "1" or v == "true" or v == "True" then
        return true
    end
    if v == false or v == 0 or v == "0" or v == "false" or v == "False" then
        return false
    end
    return default == true
end
function M.multi(id, index, default)
    local t = M.get(id)
    if type(t) ~= "table" then
        return default == true
    end
    if t[index] ~= nil then
        return as_bool(t[index], default)
    end
    if index >= 1 and t[index - 1] ~= nil then
        return as_bool(t[index - 1], default)
    end
    return default == true
end
function M.combo_index(id, labels, default)
    default = default or 0
    local v = M.get(id, default)
    if type(v) == "string" then
        local lower = v:lower()
        for i, label in ipairs(labels or {}) do
            if label:lower() == lower then return i - 1 end
        end
        return default
    end
    local n = tonumber(v)
    if n == nil then return default end
    return n
end
function M.str(id, default)
    local v = M.get(id, default)
    if v == nil then return default or "" end
    return tostring(v)
end
function M.color(id, default)
    local cached = _color_cache[id]
    if cached ~= nil then
        if cached == NIL then return default or { 1, 1, 1, 1 } end
        return cached
    end
    if menu and menu.get_color then
        local c = menu.get_color(id)
        _color_cache[id] = c or NIL
        if c then return c end
    end
    _color_cache[id] = NIL
    return default or { 1, 1, 1, 1 }
end
function M.on_change(id, fn)
    if not id or not fn then return end
    _callbacks[id] = _callbacks[id] or {}
    _callbacks[id][#_callbacks[id] + 1] = fn
    if menu and menu.set_callback then
        menu.set_callback(id, function(new_val)
            M.invalidate(id)
            for _, cb in ipairs(_callbacks[id] or {}) do
                pcall(cb, new_val)
            end
        end)
    end
end
function M.flush() end
function M.mark_dirty() end
return M
end)()

JMTECH._mods["core.feature_bind"] = (function()
