end
function M.map_png(asset_id)
    asset_id = digits(asset_id)
    if not asset_id then return nil end
    return M.CDN_BASE .. "/maps/" .. asset_id .. ".png"
end
function M.map_crop_urls(asset_id, cx, cy, cw, ch, out_w, out_h)
