    local source = string.format(
        "raw.githubusercontent.com/Cunzaki/April/refs/heads/main/assets/maps/%s.png",
        asset_id
    )
    local query = string.format(
        "?url=%s&cx=%d&cy=%d&cw=%d&ch=%d&precrop&w=%d&h=%d&fit=fill&output=png",
        source,
