    end
    M._master_hooked[master_id] = true
    local function sync()
        apply_master_tree()
        for i = 1, #M._when_rules do
            local rule = M._when_rules[i]
            if rule.sync and rule.watch and rule.watch[master_id] then
                rule.sync()
