end
local function build_radii(base, max_r)
local radii = {}
local r = base
local step = r < 0.5 and 0.10 or (r < 1 and 0.16 or 0.45)
while r < max_r - 0.04 do
radii[#radii + 1] = r
r = r + step
step = r < 1 and 0.16 or (r < 3 and 0.40 or 0.55)
end
radii[#radii + 1] = max_r
