job.ai = job.ai + 1
elseif job.phase == 2 then
if job.ai >= steps then
if radius <= 2.0 then
job.phase = 3
else
job.yi = job.yi + 1
job.phase = 1
end
job.ai = 0
return nil, false
end
angle = (job.ai / steps) * math.pi * 2
use_r = radius
job.ai = job.ai + 1
else
local diag = math.max(6, math.floor(steps * 0.3))
if job.ai >= diag then
job.yi = job.yi + 1
job.phase = 1
job.ai = 0
