esp_util.draw_world_line(wx + s, wy - s, wz - s, wx + s, wy - s, wz + s, col, thick)
esp_util.draw_world_line(wx + s, wy - s, wz + s, wx - s, wy - s, wz + s, col, thick)
esp_util.draw_world_line(wx - s, wy - s, wz + s, wx - s, wy - s, wz - s, col, thick)
esp_util.draw_world_line(wx - s, wy + s, wz - s, wx + s, wy + s, wz - s, col, thick)
esp_util.draw_world_line(wx + s, wy + s, wz - s, wx + s, wy + s, wz + s, col, thick)
esp_util.draw_world_line(wx + s, wy + s, wz + s, wx - s, wy + s, wz + s, col, thick)
esp_util.draw_world_line(wx - s, wy + s, wz + s, wx - s, wy + s, wz - s, col, thick)
esp_util.draw_world_line(wx - s, wy - s, wz - s, wx - s, wy + s, wz - s, col, thick)
esp_util.draw_world_line(wx + s, wy - s, wz - s, wx + s, wy + s, wz - s, col, thick)
esp_util.draw_world_line(wx + s, wy - s, wz + s, wx + s, wy + s, wz + s, col, thick)
esp_util.draw_world_line(wx - s, wy - s, wz + s, wx - s, wy + s, wz + s, col, thick)
end
function M.draw_cross(wx, wy, wz, size, col, thick)
