end)()

JMTECH._mods["core.angle_util"] = (function()
local env = JMTECH.require("core.env")
local math_util = JMTECH.require("core.math_util")
local M = {}
function M.normalize_yaw(y)
    while y > math.pi do y = y - math.pi * 2 end
    while y < -math.pi do y = y + math.pi * 2 end
    return y
end
function M.yaw_delta(from_yaw, to_yaw)
