    ["Military Grenade Launcher"] = { speed = 85, gravity = 0.15 },
    ["Salvaged Grenade Launcher"] = { speed = 85, gravity = 0.15 },
    ["Wooden Spear"] = { speed = 130, gravity = 0.35 },
    ["Stone Spear"] = { speed = 150, gravity = 0.35 },
