JMTECH._mods["features.combat.targeting"] = (function()
local settings = JMTECH.require("core.settings")
local weapons = JMTECH.require("game.weapons")
local ballistic = JMTECH.require("core.ballistic")
local combat_origin = JMTECH.require("game.combat_origin")
local combat_menu = JMTECH.require("features.combat.combat_menu")
local math_util = JMTECH.require("core.math_util")
local esp_util = JMTECH.require("core.esp_util")
local ep = JMTECH.require("core.entity_props")
local player_state = JMTECH.require("game.player_state")
local npcs = JMTECH.require("game.npcs")
local silent_whitelist = JMTECH.require("features.combat.silent_whitelist")
local cache = JMTECH.require("core.cache")
local env = JMTECH.require("core.env")
local M = {}
M.BONES = esp_util.AIM_BONES
local function w2s(x, y, z)
return esp_util.w2s(x, y, z)
end
function M.is_npc_target(target)
return target and target.is_npc == true
end
local function same_npc_inst(a, b)
if not a or not b then return false end
if a == b then return true end
local aa = a.Address or a.address
local ba = b.Address or b.address
return aa ~= nil and aa == ba
end
function M.same_target(a, b)
if a == nil or b == nil then return a == b end
if a == b then return true end
if M.is_npc_target(a) or M.is_npc_target(b) then
if not (M.is_npc_target(a) and M.is_npc_target(b)) then return false end
if a.entity and b.entity and a.entity == b.entity then return true end
return same_npc_inst(a.inst, b.inst)
end
local au = a.UserId or a.user_id or a.userid
local bu = b.UserId or b.user_id or b.userid
if au and bu then return tostring(au) == tostring(bu) end
local aa = a.Address or a.address
local ba = b.Address or b.address
return aa ~= nil and aa == ba
end
local function npc_enabled(entry, prefix)
if not entry then return false end
local kind = entry.kind or npcs.kind(entry.name or entry.raw_name)
return combat_menu.npc_kind_enabled(kind, prefix)
end
function M.is_npc_alive(entry)
if not entry then return false end
if entry.entity then
if entry.entity.IsAlive == false or entry.entity.is_alive == false then return false end
local hp = tonumber(entry.entity.Health or entry.entity.health)
return hp == nil or hp > 0
end
if not entry.inst or not env.is_valid(entry.inst) then return false end
local health = npcs.read_health(entry.inst, entry.humanoid)
return health ~= nil
end
function M.is_aim_target(target)
if M.is_npc_target(target) then
return M.is_npc_alive(target)
end
return player_state.is_combat_target(target)
end
local function npc_aim_world(entry, cx, cy)
if not entry then
return nil
end
local kind = entry.kind or npcs.kind(entry.name or entry.raw_name)
if kind == "heli" then
local heli = npcs.heli_aim_world(entry, true, cx, cy)
if heli then
entry.lx, entry.ly, entry.lz = heli.x, heli.y, heli.z
return heli
end
end
if entry.entity then
