end
return bone
end
function M.bow_aim_nudge(point, weapon_name)
if not point or not is_wooden_bow(weapon_name) then
return point
end
return {
x = point.x,
y = point.y + WOODEN_BOW_AIM_Y_NUDGE,
z = point.z,
