tp = "Bullet TP",
hitscan = "Hitscan",
ready = "Manip Peek",
direct = "Clear LOS",
curve = "Ballistic",
blocked = "Blocked",
scanning = "Scanning",
off = "Idle",
}
local MANIP_LABELS = {
direct = "Clear LOS",
ready = "Peek Ready",
scanning = "Scanning",
blocked = "No Peek",
off = "Off",
