    if not dist and origin then
        local pos = ep.head_position(target) or ep.position(target)
        local x, y, z = esp_util.vec3_pos(pos)
        if x then
            local dx, dy, dz = x - origin.x, y - origin.y, z - origin.z
            dist = math.sqrt(dx * dx + dy * dy + dz * dz)
