D.TOOL_MS = 150
D.MOVE_SAMPLE_MS = 900
D.RECOVER_MS = 650
D.SKIP_MS = 10000
D.NO_PROGRESS_MS = 20000
D.AIM_DOT = { approach = 0.78, body = 0.90, weak = 0.96 }
D.PHASE = {
IDLE = "Idle",
SCAN = "Scan",
APPROACH = "Approach",
PRIME = "Prime",
HARVEST = "Harvest",
RECOVER = "Recover",
DONE = "Done",
}
D.phase = D.PHASE.IDLE
D.phase_reason = nil
