M.my = 0
M.raw_mx = 0
M.raw_my = 0
M.lmb = false
M.rmb = false
M.mmb = false
M.lmb_click = false
M.rmb_click = false
M.mmb_click = false
M.lmb_release = false
M.wheel = 0
M.wheel_source = nil
M._wheel_accum = 0
M._scroll_ready = false
M._scroll_hook_tries = 0
M._event_scroll_ready = false
M._api_readers = nil
