else
    amx, amy = M.raw_mx or 0, M.raw_my or 0
end
amx = tonumber(amx) or 0
amy = tonumber(amy) or 0
M.raw_mx, M.raw_my = amx, amy
M.mx, M.my = amx, amy
M.lmb = M.key_down(0x01)
M.rmb = M.key_down(0x02)
M.mmb = M.key_down(0x04)
