M.rmb_click = M.rmb and not prev_rmb
M.mmb_click = M.mmb and not prev_mmb
M.lmb_release = (not M.lmb) and prev_lmb
prev_lmb = M.lmb
prev_rmb = M.rmb
prev_mmb = M.mmb
