local ax = bx + bw - 12
local ay = by + bh * 0.5
if open then
line(ax - 3, ay + 2, ax, ay - 1, arrow_col, 1.3)
line(ax, ay - 1, ax + 3, ay + 2, arrow_col, 1.3)
else
line(ax - 3, ay - 1, ax, ay + 2, arrow_col, 1.3)
line(ax, ay + 2, ax + 3, ay - 1, arrow_col, 1.3)
end
