anim.draw_scroll_thumb(bx + bw - 4, ty, 3, thumb_h)
end
if input.hover(bx, by, bw, bh + list_h) and input.lmb_click and not M.block_under then
mark_interacted()
end
return h + list_h
end
return h
end
