local incremental_scan = JMTECH.require("core.incremental_scan")
local rbx_offsets = JMTECH.require("core.rbx_offsets")
local M = {}
M.features = {}
M._menu_registered = false
M._update_dispatch = {}
M._draw_dispatch = {}
M.FEATURE_ORDER = {
    "features.combat.camera_aimbot",
    "features.combat.thick_bullet",
    "features.combat.aimbot",
