    "features.utility.keybind_viewer",
    "features.utility.anime_announcer",
    "features.utility.config",
}
function M.register_all()
    if M._menu_registered then return end
    menu_util.ensure_groups()
    M.features = {}
    M._update_dispatch = {}
    M._draw_dispatch = {}
    local registered = 0
    for _, path in ipairs(M.FEATURE_ORDER) do
        local feat = JMTECH.require(path)
        table.insert(M.features, feat)
        if type(feat.update) == "function" then
            M._update_dispatch[#M._update_dispatch + 1] = {
                name = "update:" .. path,
                fn = feat.update,
            }
        end
        if type(feat.draw) == "function" then
            M._draw_dispatch[#M._draw_dispatch + 1] = {
                name = "draw:" .. path,
                fn = feat.draw,
            }
        end
        if feat.register_menu then
            local ok = pcall(feat.register_menu)
            if ok then
                registered = registered + 1
            end
        end
    end
    M._menu_registered = true
    pcall(function()
        local mod = JMTECH.require("features.utility.mod_checker")
        if mod.init then mod.init() end
    end)
end
function M.setup_scans()
    local settings = JMTECH.require("core.settings")
    local cache = JMTECH.require("core.cache")
    local iscan = JMTECH.require("core.incremental_scan")
    local world_esp = JMTECH.require("features.world.world_esp")
    local loot_esp = JMTECH.require("features.world.loot_esp")
    local base_esp = JMTECH.require("features.world.base_esp")
    iscan.configure({ budget_ms = 6, items_per_step = 18 })
    local SCAN_MS = cache.WORKSPACE_SCAN_MS or 1000
    local DROPS_SCAN_MS = cache.DROPS_SCAN_MS or 3500
    local function map_on(layer)
        return function()
            if not settings.enabled("april_map_enabled") then return false end
            return settings.enabled("april_map_show_" .. layer)
        end
    end
    iscan.register("world", SCAN_MS, function()
        return settings.enabled("april_world_enabled") or map_on("world")()
    end, world_esp.begin_static_scan, world_esp.step_static_scan, world_esp.complete_static_scan, 0)
    iscan.register("world_dynamic", SCAN_MS, function()
        if not settings.enabled("april_world_enabled") then return false end
        return settings.enabled("april_deer")
            or settings.enabled("april_boar")
            or settings.enabled("april_wolf")
    end, world_esp.begin_dynamic_scan, world_esp.step_dynamic_scan, world_esp.complete_dynamic_scan, 120)
    iscan.register("loot", SCAN_MS, function()
        return settings.enabled("april_loot_enabled") or map_on("loot")()
    end, loot_esp.begin_static_scan, loot_esp.step_static_scan, loot_esp.complete_static_scan, 240)
    iscan.register("loot_drops", DROPS_SCAN_MS, function()
        if settings.enabled("april_loot_enabled") then
            return settings.enabled("april_dropped_item")
        end
        return map_on("loot")()
    end, loot_esp.begin_drops_scan, loot_esp.step_drops_scan, loot_esp.complete_drops_scan, 360)
    iscan.register("base", SCAN_MS, function()
        return settings.enabled("april_base_enabled") or map_on("base")()
    end, base_esp.begin_static_scan, base_esp.step_static_scan, base_esp.complete_static_scan, 480)
end
function M.update(dt)
    cache.refresh_entities()
    npcs.refresh_cache(cache.workspace_entities)
    player_state.tick(cache.players)
    bootstrap.tick()
    weapons.tick()
    runservice.dispatch(dt)
    incremental_scan.tick()
    pcall(rbx_offsets.tick_fps)
    for i = 1, #M._update_dispatch do
        local call = M._update_dispatch[i]
        debug.guard_fast(call.name, call.fn, dt)
    end
end
function M.draw()
    for i = 1, #M._draw_dispatch do
        local call = M._draw_dispatch[i]
        debug.guard_fast(call.name, call.fn)
    end
end
function M.init()
    local env = JMTECH.require("core.env")
    local ok = env.require_apis({ "draw", "utility", "entity", "game" })
    if not ok then
        return false
    end
    pcall(function()
        JMTECH.require("ui.menu_shim").install()
    end)
    pcall(function()
        JMTECH.require("core.rbx_offsets").boot()
    end)
    M.register_all()
    M.setup_scans()
    M.setup_player_hooks()
    pcall(function()
        JMTECH.require("features.utility.config").try_autoload()
    end)
    return true
end
function M.setup_player_hooks()
    local mod = JMTECH.require("features.utility.mod_checker")
    _G.on_player_added = function(p)
        debug.guard_fast("on_player_added", mod.on_player_added, p)
    end
    _G.on_player_removed = function(p)
        debug.guard_fast("on_player_removed", mod.on_player_removed, p)
    end
end
return M
end)()

JMTECH._mods["app"] = (function()
local tabs = JMTECH.require("menu.tabs")
local debug = JMTECH.require("core.debug")
local notify = JMTECH.require("core.notify")
local custom_menu = JMTECH.require("ui.custom_menu")
local startup_intro = JMTECH.require("ui.startup_intro")
local api_aliases = JMTECH.require("core.api_aliases")
local feature_bind = JMTECH.require("core.feature_bind")
local aim_key = JMTECH.require("core.aim_key")
local overlay_theme = JMTECH.require("core.overlay_theme")
local settings = JMTECH.require("core.settings")
local image_cache = JMTECH.require("core.image_cache")
local manip_math = JMTECH.require("core.manip_math")
local M = {}
local initialized = false
local alias_refresh_elapsed = 0
-- JMTECH UI-only performance monitor; does not read or change targeting logic.
local jmtech_ui_last_report = 0
local jmtech_ui_sample_counter = 0
local function jmtech_ui_tick_ms()
    local fn = utility and (utility.GetTickCount or utility.get_tick_count)
    if type(fn) ~= "function" then return nil end
    local ok, value = pcall(fn)
    if ok and type(value) == "number" and value == value then return value end
    return nil
end
local function jmtech_ui_draw_guarded()
    -- Sample only every 30th frame to avoid adding work to the renderer.
    jmtech_ui_sample_counter = jmtech_ui_sample_counter + 1
    local sample = (jmtech_ui_sample_counter % 30 == 0)
    local before = sample and jmtech_ui_tick_ms() or nil
    debug.guard_fast("custom_menu.draw", custom_menu.draw)
    if before then
        local after = jmtech_ui_tick_ms()
        if after and after >= before then
            local elapsed = after - before
            if elapsed >= 33 and (after - jmtech_ui_last_report) >= 10000 then
                jmtech_ui_last_report = after
                print(string.format("[JMTECH UI] menu draw %d ms (sampled); check FPS/overlay load", elapsed))
            end
        end
    end
end
function M.init()
    if initialized then return true end
    pcall(function()
        JMTECH.require("core.entity_props").ensure_api_aliases()
    end)
    initialized = tabs.init()
    if initialized then
        pcall(custom_menu.init)
        pcall(startup_intro.init)
    end
    return initialized
end
function M.on_frame()
    if not initialized then return end
    debug.tick_frame()
    settings.begin_frame(debug.frame_count())
    image_cache.prune()
    manip_math.prune_caches()
    pcall(feature_bind.tick)
    pcall(aim_key.tick, "april_aim_key", "april_aim_key_mode")
    if startup_intro.is_active() then
        if startup_intro.should_reveal_menu() then
            debug.guard_fast("custom_menu.draw:intro", custom_menu.draw)
        end
        local ok = pcall(startup_intro.draw)
        if ok then
            return
        end
        startup_intro.cancel()
    end
    local dt = 0.016
    if utility and utility.get_delta_time then
        local ok, v = pcall(utility.get_delta_time)
        if ok and type(v) == "number" then dt = v end
    end
    alias_refresh_elapsed = alias_refresh_elapsed + dt
    if alias_refresh_elapsed >= 2 then
        alias_refresh_elapsed = 0
        pcall(api_aliases.apply)
    end
    debug.guard_fast("tabs.update", tabs.update, dt)
    debug.guard_fast("overlay_theme.sync", overlay_theme.sync)
    debug.guard_fast("tabs.draw", tabs.draw)
    debug.guard_fast("notify.draw", notify.draw)
    jmtech_ui_draw_guarded()
end
return M
end)()

do
    JMTECH.require("ui.menu_shim").install()
    JMTECH.require("menu.tabs").register_all()
end

JMTECH._init_ok = false

local ok, err = pcall(function()
    local debug = JMTECH.require("core.debug")
    local caps = JMTECH.require("core.capabilities")
    local app = JMTECH.require("app")

    if not app.init() then
        return
    end

    JMTECH.require("core.api_aliases").apply()
    JMTECH.require("core.movement_ctrl").install()
    JMTECH.require("core.spider_ctrl").install()
    JMTECH.require("features.movement.fling").install()
    JMTECH.require("features.movement.anti_aim").install()
    JMTECH.require("features.movement.anti_fling").install()
    JMTECH.require("features.world.base_xray").install()
    JMTECH.require("features.movement.fake_duck").install()

    JMTECH._init_ok = true

    local c = caps.probe()
    if c.fallen_gc then
        JMTECH.require("game.gc_weapon_mods").probe_on_load()
    end

    debug.register_frame_hook(function()
        app.on_frame()
    end)
end)

if not ok then
    print("[JMTECH] Fatal: " .. tostring(err))
end
